using Microsoft.EntityFrameworkCore;using MongoDB.Driver;using ZosyalMedya.BuildingBlocks.Application.Persistence;using ZosyalMedya.Modules.Comments.Application.Ports;using ZosyalMedya.Modules.Comments.Domain.Comments;using ZosyalMedya.Modules.Comments.Infrastructure.Persistence.MongoDb;using ZosyalMedya.Modules.Comments.Infrastructure.Persistence.PostgreSql;using ZosyalMedya.Modules.Reactions.Application.Ports;using ZosyalMedya.Modules.Reactions.Domain.Reactions;using ZosyalMedya.Modules.Reactions.Infrastructure.Persistence.MongoDb;using ZosyalMedya.Modules.Reactions.Infrastructure.Persistence.PostgreSql;using Xunit;
namespace ZosyalMedya.Tests.Integration.Persistence;
public abstract class ReactionRepositoryContractTests{protected abstract Task<IReactionRepository>CreateRepositoryAsync();[Fact]public async Task UniqueIdempotentUpdateSummaryAndDeleteBehaveEqually(){if(!InfrastructureTestGate.IsEnabled)return;var r=await CreateRepositoryAsync();var actor=new ReactionActorId(Guid.NewGuid());var content=new ReactedContentId(Guid.NewGuid());var item=Reaction.Create(ReactionId.New(),actor,content,ReactionKind.Like,DateTimeOffset.UtcNow);await r.CreateAsync(item);await Assert.ThrowsAsync<PersistenceConflictException>(()=>r.CreateAsync(Reaction.Create(ReactionId.New(),actor,content,ReactionKind.Love,DateTimeOffset.UtcNow)));var version=item.Version;item.Set(ReactionKind.Love,DateTimeOffset.UtcNow);Assert.True(await r.UpdateAsync(x=>x.Id==item.Id,item,version));Assert.False(await r.UpdateAsync(x=>x.Id==item.Id,item,version));var counts=await r.CountActiveByContentAsync(content);Assert.Equal(1,counts[ReactionKind.Love]);Assert.Equal(1,await r.DeleteByFilterAsync(x=>x.Id==item.Id));}}
public sealed class PostgreSqlReactionRepositoryContractTests:ReactionRepositoryContractTests{protected override async Task<IReactionRepository>CreateRepositoryAsync(){var db=new ReactionsDbContext(new DbContextOptionsBuilder<ReactionsDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();return new PostgreSqlReactionRepository(db);}}
public sealed class MongoReactionRepositoryContractTests:ReactionRepositoryContractTests{protected override async Task<IReactionRepository>CreateRepositoryAsync(){var r=new MongoReactionRepository(new MongoClient("mongodb://localhost:57017").GetDatabase("zosyalmedya_contract_tests"));await r.EnsureIndexesAsync(CancellationToken.None);return r;}}
public abstract class CommentRepositoryContractTests{protected abstract Task<ICommentRepository>CreateRepositoryAsync();[Fact]public async Task CreateSortUpdateCountAndDeleteBehaveEqually(){if(!InfrastructureTestGate.IsEnabled)return;var r=await CreateRepositoryAsync();var author=new CommentAuthorId(Guid.NewGuid());var content=new CommentedContentId(Guid.NewGuid());var item=Comment.Create(CommentId.New(),author,content,null,0,"Contract comment",DateTimeOffset.UtcNow);await r.CreateAsync(item);Assert.Single(await r.ListByFilterAsync(x=>x.ContentId==content));Assert.Equal(1,await r.CountVisibleAsync(content));var v=item.Version;item.Edit(author,"Updated comment",DateTimeOffset.UtcNow);Assert.True(await r.UpdateAsync(x=>x.Id==item.Id,item,v));Assert.False(await r.UpdateAsync(x=>x.Id==item.Id,item,v));Assert.Equal(1,await r.DeleteByFilterAsync(x=>x.Id==item.Id));}[Fact]public async Task KeysetPageIncludesDeletedTombstonesAndDoesNotRepeat(){if(!InfrastructureTestGate.IsEnabled)return;var r=await CreateRepositoryAsync();var author=new CommentAuthorId(Guid.NewGuid());var content=new CommentedContentId(Guid.NewGuid());var now=DateTimeOffset.UtcNow;var first=Comment.Create(CommentId.New(),author,content,null,0,"first",now);var deleted=Comment.Create(CommentId.New(),author,content,null,0,"deleted",now.AddSeconds(1));deleted.Delete(author,now.AddSeconds(2));var last=Comment.Create(CommentId.New(),author,content,null,0,"last",now.AddSeconds(3));await r.CreateAsync(first);await r.CreateAsync(deleted);await r.CreateAsync(last);var page1=await r.ListPageAsync(new(content,null,null,2));Assert.Equal(2,page1.Count);Assert.Equal(CommentStatus.Deleted,page1[1].Status);var page2=await r.ListPageAsync(new(content,page1[^1].CreatedAtUtc,page1[^1].Id,2));Assert.Single(page2);Assert.Equal(last.Id,page2[0].Id);Assert.DoesNotContain(page2,x=>page1.Any(y=>y.Id==x.Id));}}
public sealed class PostgreSqlCommentRepositoryContractTests:CommentRepositoryContractTests{protected override async Task<ICommentRepository>CreateRepositoryAsync(){var db=new CommentsDbContext(new DbContextOptionsBuilder<CommentsDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();return new PostgreSqlCommentRepository(db);}}
public sealed class MongoCommentRepositoryContractTests:CommentRepositoryContractTests{protected override async Task<ICommentRepository>CreateRepositoryAsync(){var r=new MongoCommentRepository(new MongoClient("mongodb://localhost:57017").GetDatabase("zosyalmedya_contract_tests"));await r.EnsureIndexesAsync(CancellationToken.None);return r;}}
